/// 由 JsObject 持有 napi 强引用；Dispose 仅释放引用，JS 对象由 ArkTS GC 管理。
/// </summary>
public sealed partial class BundleStatsInfo : JsObject
{
    public BundleStatsInfo(IntPtr handle) : base(handle) { }
    private static ReadOnlySpan<byte> _bundleName => "bundleName"u8;
    private static ReadOnlySpan<byte> _appIndex => "appIndex"u8;
    private static ReadOnlySpan<byte> _abilityInFgTotalTime => "abilityInFgTotalTime"u8;
    /// <summary>
    /// bundleName
    /// </summary>
    public string BundleName => NativeValue.ToString(GetPropertyRaw(_bundleName)) ?? string.Empty;

    /// <summary>
    /// appIndex
    /// </summary>
    public double AppIndex => NativeValue.ToDouble(GetPropertyRaw(_appIndex));

    /// <summary>
    /// abilityInFgTotalTime
    /// </summary>
    public double AbilityInFgTotalTime => NativeValue.ToDouble(GetPropertyRaw(_abilityInFgTotalTime));

}

/// <summary>
/// WindowStateInfo 实例包装（@ohos 命名空间内嵌套接口）。
/// 由 JsObject 持有 napi 强引用；Dispose 仅释放引用，JS 对象由 ArkTS GC 管理。
/// </summary>
public sealed partial class WindowStateInfo : JsObject
{
    public WindowStateInfo(IntPtr handle) : base(handle) { }
    private static ReadOnlySpan<byte> _windowId => "windowId"u8;
    private static ReadOnlySpan<byte> _name => "name"u8;
    private static ReadOnlySpan<byte> _state => "state"u8;
    private static ReadOnlySpan<byte> _isOnDock => "isOnDock"u8;
    /// <summary>
    /// windowId
    /// </summary>
    public double WindowId => NativeValue.ToDouble(GetPropertyRaw(_windowId));

    /// <summary>
    /// name
    /// </summary>
    public string Name => NativeValue.ToString(GetPropertyRaw(_name)) ?? string.Empty;

    /// <summary>
    /// state
    /// </summary>
    public global::HarmonyOS.ArkUI.WindowState State => (global::HarmonyOS.ArkUI.WindowState)NativeValue.ToInt(GetPropertyRaw(_state));

    /// <summary>
    /// isOnDock
    /// </summary>
    public bool IsOnDock => NativeValue.ToBool(GetPropertyRaw(_isOnDock));

}
